import struct, socket, random

def query(name, qtype, server=('127.0.0.11',53)):
    tid = random.randint(0,65535)
    header = struct.pack('>HHHHHH', tid, 0x0100, 1, 0, 0, 0)
    parts = name.split('.')
    q = b''
    for p in parts:
        try: q += bytes([len(p)]) + int(p).to_bytes(1,'big') if p.isdigit() and len(p)<=3 else bytes([len(p)]) + p.encode()
        except: q += bytes([len(p)]) + p.encode()
    q += b'\x00' + struct.pack('>HH', qtype, 1)
    s = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    s.settimeout(2)
    s.sendto(header+q, server)
    try:
        data,_ = s.recvfrom(4096)
        ancount = struct.unpack('>H', data[6:8])[0]
        idx = 12
        while idx < len(data) and data[idx] != 0:
            idx += data[idx] + 1
        idx += 5
        outs=[]
        for _ in range(ancount):
            idx += 2
            typ, cls, ttl, rdlen = struct.unpack('>HHIH', data[idx:idx+10]); idx += 10
            rdata = data[idx:idx+rdlen]; idx += rdlen
            if typ==1: outs.append('A '+'.'.join(str(b) for b in rdata))
            elif typ==5:
                j=0; parts2=[]
                while j < len(rdata):
                    l=rdata[j]
                    if l & 0xC0 == 0xC0: parts2.append('<ptr>'); break
                    j+=1; parts2.append(rdata[j:j+l].decode()); j+=l
                outs.append('CNAME '+'.'.join(parts2))
            elif typ==28: outs.append('AAAA '+rdata.hex())
            elif typ==16: outs.append('TXT '+rdata.decode(errors='replace'))
            elif typ in (33,): # SRV
                pri,wt,port = struct.unpack('>HHH', rdata[:6])
                j=6; parts2=[]
                while j < len(rdata):
                    l=rdata[j]
                    if l & 0xC0 == 0xC0: parts2.append('<ptr>'); break
                    j+=1; parts2.append(rdata[j:j+l].decode()); j+=l
                outs.append(f'SRV pri={pri} wt={wt} port={port} target={".".join(parts2)}')
            elif typ==12: outs.append('PTR '+rdata.decode(errors='replace'))
            else: outs.append(f'type{typ} {rdata!r}')
        if outs: print(name, qtype, outs)
    except socket.timeout:
        pass
    except Exception as e:
        pass

